import os


def status():
    cfg = {}
    if os.path.exists('setup.cfg'):
        for line in open('setup.cfg'):
            if '=' in line:
                k, v = line.split('=', 1)
                cfg[k.strip()] = v.strip()
    if cfg.get('configured') != 'yes':
        return 'not set up'
    if not os.path.isdir('data'):
        return 'no data folder'
    return 'ready'

